1 to listOf(Ayah(1, "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "Bismillāhir-Raḥmānir-Raḥīm", "In the name of Allah, the Entirely Merciful, the Especially Merciful."), Ayah(2, "الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ", "Al-ḥamdu lillāhi Rabbil-'ālamīn", "All praise is due to Allah, Lord of the worlds."), Ayah(3, "الرَّحْمَٰنِ الرَّحِيمِ", "Ar-Raḥmānir-Raḥīm", "The Entirely Merciful, the Especially Merciful,"), Ayah(4, "مَالِكِ يَوْمِ الدِّينِ", "Māliki yawmid-dīn", "Sovereign of the Day of Recompense."), Ayah(5, "إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ", "Iyyāka na'budu wa iyyāka nasta'īn", "It is You we worship and You we ask for help."), Ayah(6, "اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ", "Ihdinaṣ-ṣirāṭal-mustaqīm", "Guide us to the straight path -"), Ayah(7, "صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ", "Ṣirāṭallaḏhīna an'amta 'alayhim ghayril-maghdūbi 'alayhim walāḍ-ḍāllīn", "The path of those upon whom You have bestowed favor, not of those who have evoked Your anger or of those who are astray.")), 67 to listOf(Ayah(1, "تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", "Tabārakalladhī biyadihi al-mulku wahuwa 'alā kulli shay'in qadīr", "Blessed is He in whose hand is dominion, and He is over all things competent."), Ayah(2, "الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ الْعَزِيزُ الْغَفُورُ", "Alladhī khalaqa al-mawta wal-ḥayāta liyabluwakum ayyukum aḥsanu 'amalan", "He who created death and life to test you as to which of you is best in deed - and He is the Exalted in Might, the Forgiving.")), 112 to listOf(Ayah(1, "قُلْ هُوَ اللَّهُ أَحَدٌ", "Qul huwa Allāhu aḥad", "Say, 'He is Allah, [who is] One,"), Ayah(2, "اللَّهُ الصَّمَدُ", "Allāhuṣ-ṣamad", "Allah, the Eternal Refuge."), Ayah(3, "لَمْ يَلِدْ وَلَمْ يُولَدْ", "Lam yalid walam yūlad", "He neither begets nor is born,"), Ayah(4, "وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ", "Walam yakun lahū kufuwan aḥad", "Nor is there to Him any equivalent.'")), 113 to listOf(Ayah(1, "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ", "Qul a'ūḏhu birabbil-falaq", "Say, 'I seek refuge in the Lord of daybreak"), Ayah(2, "مِن شَرِّ مَا خَلَقَ", "Min sharri mā khalaq", "From the evil of that which He created"), Ayah(3, "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ", "Wa min sharri ghāsiqin iḏhā waqab", "And from the evil of darkness when it settles"), Ayah(4, "وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ", "Wa min sharrin-naffāthāti fīl-'uqad", "And from the evil of the blowers in knots"), Ayah(5, "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ", "Wa min sharri ḥāsidin iḏhā ḥasad", "And from the evil of an envier when he envies.'")), 114 to listOf(Ayah(1, "قُلْ أَعُوذُ بِرَبِّ النَّاسِ", "Qul a'ūḏhu birabbin-nās", "Say, 'I seek refuge in the Lord of mankind,"), Ayah(2, "مَلِكِ النَّاسِ", "Malikin-nās", "The Sovereign of mankind,"), Ayah(3, "إِلَٰهِ النَّاسِ", "Ilāhin-nās", "The God of mankind,"), Ayah(4, "مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ", "Min sharril-waswāsil-khannās", "From the evil of the retreating whisperer -"), Ayah(5, "الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ", "Alladhī yuwaswisu fī ṣudūrin-nās", "Who whispers into the breasts of mankind -"), Ayah(6, "مِنَ الْجِنَّةِ وَالنَّاسِ", "Minal-jinnati wan-nās", "From among the jinn and mankind.'"))
